def is_balanced(s):
    stack = []
    matches = {')': '(', ']': '[', '}': '{'}
    for c in s:
        if c in matches:
            if not stack or stack[-1] != matches[c]:
                return False
            stack.pop()
        elif c in '([{':
            stack.append(c)
    return not stack
```

